const EnteredVehiclesTable = ({ vehicles, loading }) => {
  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow">
        <div className="p-6">
          <div className="animate-pulse">
            <div className="h-6 bg-gray-200 rounded w-1/4 mb-4"></div>
            <div className="space-y-3">
              {[1, 2, 3, 4, 5].map((i) => (
                <div key={i} className="h-12 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white rounded-lg shadow overflow-hidden">
      <div className="p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Entered Vehicles ({vehicles.length} records)</h3>

        {vehicles.length === 0 ? (
          <div className="text-center py-8 text-gray-500">No vehicle entries found</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-left py-3 px-4 font-medium text-gray-900">License Plate</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Entry Time</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Vehicle Type</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Camera ID</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Status</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Confidence</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-900">Duration</th>
                </tr>
              </thead>
              <tbody>
                {vehicles.map((vehicle, index) => {
                  const entryTime = new Date(vehicle.entryTime)
                  const currentTime = new Date()
                  const durationMs = currentTime - entryTime
                  const hours = Math.floor(durationMs / (1000 * 60 * 60))
                  const minutes = Math.floor((durationMs % (1000 * 60 * 60)) / (1000 * 60))
                  const currentDuration = `${hours}h ${minutes}m`

                  return (
                    <tr key={index} className="border-b border-gray-100 hover:bg-gray-50">
                      <td className="py-3 px-4 font-medium">{vehicle.licensePlate}</td>
                      <td className="py-3 px-4 text-gray-600">{entryTime.toLocaleString()}</td>
                      <td className="py-3 px-4">
                        <span className="px-2 py-1 bg-gray-100 text-gray-800 text-xs rounded-full">
                          {vehicle.vehicleType}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-gray-600">{vehicle.cameraId}</td>
                      <td className="py-3 px-4">
                        <span
                          className={`px-2 py-1 text-xs rounded-full ${
                            vehicle.status === "parked" ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"
                          }`}
                        >
                          {vehicle.status === "parked" ? "Currently Parked" : "Exited"}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-gray-600">
                        {vehicle.confidence ? `${Math.round(vehicle.confidence * 100)}%` : "N/A"}
                      </td>
                      <td className="py-3 px-4 text-gray-600">
                        {vehicle.status === "parked" ? currentDuration : "Completed"}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  )
}

export default EnteredVehiclesTable
